cases.script:
n(){ "$@" 2>&1 && echo rc=0 || echo "rc=$?"; }
s(){ sed 's/^[^ ]*: line [0-9]*: //'; }
mkdir sg; chmod 2755 sg
i=0; for um in 077 0 0222 022; do umask $um; for m in +t g+s g-s o=t +t,a-r g+s,-x =t u+s 01777 +t,-w u=rwx,+t a=w,+t; do i=$((i+1)); n mkdir -m "$m" m$i sg/m$i | s; done; done
umask 022; stat -c '%a %n' m* sg/m*
chmod -R u+rwx .
